#include <algorithm>
#include <iostream>

struct TreeNode {
    int value;
    TreeNode* left;
    TreeNode* right;
};

TreeNode* insert(TreeNode* node, int value) {
    if (node == nullptr) {
        return new TreeNode{value, nullptr, nullptr};
    }
    if (value < node->value) {
        node->left = insert(node->left, value);
    } else if (value > node->value) {
        node->right = insert(node->right, value);
    }
    return node;
}

int height(const TreeNode* node) {
    if (node == nullptr) {
        return 0;
    }
    return 1 + std::max(height(node->left), height(node->right));
}

int checks(const TreeNode* node, int target) {
    int count = 0;
    while (node != nullptr) {
        ++count;
        if (target == node->value) {
            break;
        }
        node = (target < node->value) ? node->left : node->right;
    }
    return count;
}

TreeNode* insertMiddleFirst(TreeNode* root, int lo, int hi) {
    if (lo > hi) {
        return root;
    }
    const int mid = lo + (hi - lo) / 2;
    root = insert(root, mid);
    root = insertMiddleFirst(root, lo, mid - 1);
    return insertMiddleFirst(root, mid + 1, hi);
}

void freeTree(TreeNode* node) {
    if (node == nullptr) {
        return;
    }
    freeTree(node->left);
    freeTree(node->right);
    delete node;
}

int main() {
    const int n = 1023;
    TreeNode* arrival = nullptr;
    for (int id = 1; id <= n; ++id) {
        arrival = insert(arrival, id);   // ids arrive in increasing order
    }
    TreeNode* middle = insertMiddleFirst(nullptr, 1, n);
    long long arrivalChecks = 0;
    long long middleChecks = 0;
    for (int id = 1; id <= n; ++id) {
        arrivalChecks += checks(arrival, id);
        middleChecks += checks(middle, id);
    }
    std::cout << "arrival order: height " << height(arrival) << ", " << arrivalChecks << " checks\n";
    std::cout << "middle first: height " << height(middle) << ", " << middleChecks << " checks\n";
    freeTree(arrival);
    freeTree(middle);
    return 0;
}

