#include <iostream>

struct TreeNode {
    int value;
    TreeNode* left;
    TreeNode* right;
};

TreeNode* insert(TreeNode* node, int value) {
    if (node == nullptr) {
        return new TreeNode{value, nullptr, nullptr};
    }
    if (value < node->value) {
        node->left = insert(node->left, value);
    } else if (value > node->value) {
        node->right = insert(node->right, value);
    }
    return node;
}

TreeNode* rotateLeft(TreeNode* x) {
    TreeNode* y = x->right;
    x->right = y->left;   // y's left subtree moves across to x
    y->left = x;
    return y;             // y now heads this subtree
}

TreeNode* rotateLeftAt(TreeNode* node, int key) {
    if (node == nullptr) {
        return nullptr;   // key isn't in the tree: nothing changes
    }
    if (key < node->value) {
        node->left = rotateLeftAt(node->left, key);
    } else if (key > node->value) {
        node->right = rotateLeftAt(node->right, key);
    } else if (node->right != nullptr) {
        return rotateLeft(node);
    }
    return node;
}

void show(const TreeNode* node) {   // (left subtree, value, right subtree)
    if (node == nullptr) {
        return;
    }
    std::cout << '(';
    show(node->left);
    std::cout << node->value;
    show(node->right);
    std::cout << ')';
}

void freeTree(TreeNode* node) {
    if (node == nullptr) {
        return;
    }
    freeTree(node->left);
    freeTree(node->right);
    delete node;
}

int main() {
    TreeNode* root = nullptr;
    char op = ' ';
    int key = 0;
    while (std::cin >> op >> key) {
        if (op == '+') {
            root = insert(root, key);
        } else {
            root = rotateLeftAt(root, key);
        }
        std::cout << op << ' ' << key << ": ";
        show(root);
        std::cout << '\n';
    }
    freeTree(root);
    return 0;
}

