#include <algorithm>
#include <iostream>

struct AvlNode {
    int value;
    int height;   // levels in this subtree: 1 for a leaf
    AvlNode* left;
    AvlNode* right;
};

int height(const AvlNode* node) { return node == nullptr ? 0 : node->height; }

AvlNode* fixHeight(AvlNode* node) {
    node->height = 1 + std::max(height(node->left), height(node->right));
    return node;
}

AvlNode* rotateRight(AvlNode* y) {
    AvlNode* x = y->left;
    y->left = x->right;
    x->right = fixHeight(y);   // y is now below x, so its height is fixed first
    return fixHeight(x);
}

AvlNode* rotateLeft(AvlNode* x) {
    AvlNode* y = x->right;
    x->right = y->left;
    y->left = fixHeight(x);
    return fixHeight(y);
}

AvlNode* rebalance(AvlNode* node) {
    const int balance = height(node->left) - height(node->right);
    if (balance > 1) {                     // too tall on the left
        if (height(node->left->right) > height(node->left->left)) {
            node->left = rotateLeft(node->left);   // left-right: straighten the bend
        }
        return rotateRight(node);
    }
    if (balance < -1) {                    // too tall on the right
        if (height(node->right->left) > height(node->right->right)) {
            node->right = rotateRight(node->right);   // right-left
        }
        return rotateLeft(node);
    }
    return fixHeight(node);
}

AvlNode* insert(AvlNode* node, int value) {
    if (node == nullptr) {
        return new AvlNode{value, 1, nullptr, nullptr};
    }
    if (value < node->value) {
        node->left = insert(node->left, value);
    } else if (value > node->value) {
        node->right = insert(node->right, value);
    }
    return rebalance(node);
}

void freeTree(AvlNode* node) {
    if (node == nullptr) {
        return;
    }
    freeTree(node->left);
    freeTree(node->right);
    delete node;
}

int main() {
    AvlNode* root = nullptr;
    for (int id = 1; id <= 100000; ++id) {
        root = insert(root, id);   // every id is the largest so far
    }
    std::cout << "100000 ids: height " << height(root) << ", root " << root->value << '\n';
    freeTree(root);
    return 0;
}

