    node->left = build(in);
    node->right = build(in);
    return node;
}

int audit(const RbNode* node, long long low, long long high) {
    if (node == nullptr) {
        return 0;
    }
    const int left = audit(node->left, low, node->value);
    if (left == -1) {
        return -1;
    }
    const int right = audit(node->right, node->value, high);
    if (right == -1) {
        return -1;
    }
    if (node->value <= low || node->value >= high) {
        std::cout << node->value << " is out of order\n";
        return -1;
    }
    if (node->red && (isRed(node->left) || isRed(node->right))) {
        std::cout << "red " << node->value << " has a red child\n";
        return -1;
    }
    if (left != right) {
        std::cout << "black heights differ below " << node->value << '\n';
        return -1;
    }
    return left + (node->red ? 0 : 1);
}

void freeTree(RbNode* node) {
    if (node == nullptr) {
        return;
    }
    freeTree(node->left);
    freeTree(node->right);
    delete node;
}

